// Extract book title from webhook body
const bookTitle = $input.item.json.body.bookTitle || $input.item.json.bookTitle;

if (!bookTitle) {
  throw new Error('bookTitle is required');
}

// Validate title
if (typeof bookTitle !== 'string' || bookTitle.trim().length === 0) {
  throw new Error('bookTitle must be a non-empty string');
}

return {
  bookTitle: bookTitle.trim(),
  requestedAt: new Date().toISOString()
};

// Check if MCP Server response was successful
const data = $input.item.json;

if (data.success === true) {
  // Success case - pass through the data
  return [data];
} else {
  // Error case - throw error to stop workflow
  throw new Error(`Analysis failed: ${data.error || 'Unknown error'}`);
}

// Format successful response
const data = $input.item.json;

return {
  success: true,
  bookInfo: {
    title: data.bookInfo.title,
    authors: data.bookInfo.authors,
    publishedDate: data.bookInfo.publishedDate,
    isbn: data.bookInfo.isbn,
    categories: data.bookInfo.categories,
    thumbnail: data.bookInfo.thumbnail,
    infoLink: data.bookInfo.infoLink
  },
  summary: data.analysis.summary,
  keyIdeas: data.analysis.keyIdeas,
  audioFile: data.audio ? data.audio.filename : null,
  audioPath: data.audio ? data.audio.path : null,
  audioDownloadUrl: data.audio ? `http://localhost:3000/audio/${data.audio.filename}` : null,
  metadata: {
    analyzedAt: data.metadata.analyzedAt,
    llmModel: data.metadata.llmModel
  }
};
